Keep one running total across the loop and push a copy of it on every turn. The array is the record of that total.

code:
function prefixSums(arr) {
  const out = [];
  let running = 0;
  for (const n of arr) {
    running += n;
    out.push(running);
  }
  return out;
}
console.log(prefixSums([1, 2, 3, 4])); // [ 1, 3, 6, 10 ]

output:
[ 1, 3, 6, 10 ]

Returning false early stops the scan on the first failure. Reaching the end of the loop means every number passed.

code:
function everyAtLeast(nums, limit) {
  for (const n of nums) {
    if (n < limit) return false;
  }
  return true;
}
console.log(everyAtLeast([5, 6, 7], 5), everyAtLeast([5, 2], 5)); // true false

output:
true false

Keep assigning while the condition holds, so the final assignment is the last match. Report null when nothing ever matched.

code:
function someAbove(nums, limit) {
  let found = null;
  for (const n of nums) {
    if (n > limit) found = n;
  }
  return found;
}
console.log(someAbove([1, 9, 3, 11], 5), someAbove([1, 2], 5)); // 11 null

output:
11 null

Bubble sort compares each neighbouring pair and swaps them when they are in the wrong order. Each full pass settles the largest remaining value at the end, so the inner loop gets shorter.

code:
const arr = [5, 1, 4, 2, 8];
const sorted = arr.slice();
for (let pass = 0; pass < sorted.length; pass++) {
  for (let i = 0; i < sorted.length - pass - 1; i++) {
    if (sorted[i] > sorted[i + 1]) {
      const swap = sorted[i];
      sorted[i] = sorted[i + 1];
      sorted[i + 1] = swap;
    }
  }
}
console.log('before', arr.join(','));
console.log('after', sorted.join(','));

output:
before 5,1,4,2,8
after 1,2,4,5,8

Take the next value, then shift every larger value one place to the right and drop the value into the gap. That is insertion sort.

code:
const arr = [5, 2, 4, 6, 1];
for (let i = 1; i < arr.length; i++) {
  const value = arr[i];
  let j = i - 1;
  while (j >= 0 && arr[j] > value) {
    arr[j + 1] = arr[j];
    j--;
  }
  arr[j + 1] = value;
}
console.log(arr); // [ 1, 2, 4, 5, 6 ]

output:
[ 1, 2, 4, 5, 6 ]

A loop repeats the same shift k times. Shifting pulls the front value off and pushes it on the end.

code:
function rotate(arr, k) {
  const out = arr.slice();
  for (let i = 0; i < k; i++) {
    out.push(out.shift());
  }
  return out;
}
console.log(rotate([1, 2, 3, 4, 5], 2).join(' ')); // 3 4 5 1 2

output:
3 4 5 1 2

Move the index by the chunk size on every turn. The last chunk is shorter because slice just runs off the end.

code:
const arr = [1, 2, 3, 4, 5, 6, 7];
const chunks = [];
for (let i = 0; i < arr.length; i += 3) {
  chunks.push(arr.slice(i, i + 3));
}
console.log(chunks);

output:
[ [ 1, 2, 3 ], [ 4, 5, 6 ], [ 7 ] ]

One level means the inner arrays disappear but their contents stay. Two loops express exactly that.

code:
const nested = [[1, 2], [3, 4], [5]];
const flat = [];
for (let i = 0; i < nested.length; i++) {
  for (let j = 0; j < nested[i].length; j++) {
    flat.push(nested[i][j]);
  }
}
console.log(flat); // [ 1, 2, 3, 4, 5 ]

output:
[ 1, 2, 3, 4, 5 ]

Compare the two front values, push the smaller one and move only that pointer. When one list runs dry, copy the rest of the other.

code:
const left = [1, 3, 5];
const right = [2, 4, 6];
const merged = [];
let i = 0;
let j = 0;
while (i < left.length && j < right.length) {
  if (left[i] <= right[j]) merged.push(left[i++]);
  else merged.push(right[j++]);
}
while (i < left.length) merged.push(left[i++]);
while (j < right.length) merged.push(right[j++]);
console.log(merged); // [ 1, 2, 3, 4, 5, 6 ]

output:
[ 1, 2, 3, 4, 5, 6 ]

Element at row r column c goes to row c column r. Create the new grid with the swapped dimensions first, then fill it.

code:
const matrix = [[1, 2, 3], [4, 5, 6]];
const rows = matrix.length;
const cols = matrix[0].length;
const out = Array(cols).fill().map(() => Array(rows).fill(0));
for (let r = 0; r < rows; r++) {
  for (let c = 0; c < cols; c++) {
    out[c][r] = matrix[r][c];
  }
}
console.log(out); // [ [ 1, 4 ], [ 2, 5 ], [ 3, 6 ] ]

output:
[ [ 1, 4 ], [ 2, 5 ], [ 3, 6 ] ]

Start at 2 because every number divides itself. Once the divisor passes the square root there is nothing left to test.

code:
function isPrime(n) {
  if (n < 2) return false;
  for (let i = 2; i * i <= n; i++) {
    if (n % i === 0) return false;
  }
  return true;
}
console.log([2, 9, 17, 1].map(isPrime).join(' ')); // true false true false

output:
true false true false

Count the primes as you find them and stop the outer loop once the count reaches n. Test divisors with the cheaper i times i limit.

code:
function nthPrime(n) {
  let count = 0;
  let candidate = 1;
  while (count < n) {
    candidate++;
    let prime = true;
    for (let i = 2; i * i <= candidate; i++) {
      if (candidate % i === 0) prime = false;
    }
    if (prime) count++;
  }
  return candidate;
}
console.log(nthPrime(7)); // 17

output:
17

Two pointers walk towards each other. The first mismatch means it is not a palindrome, and meeting in the middle means it is.

code:
function isPalindrome(s) {
  let left = 0;
  let right = s.length - 1;
  while (left < right) {
    if (s[left] !== s[right]) return false;
    left++;
    right--;
  }
  return true;
}
console.log(isPalindrome('radar'), isPalindrome('runner')); // true false

output:
true false

The sorted letters make a good group key. Every word with the same key belongs to the same group.

code:
const words = ['listen', 'silent', 'google', 'enlist'];
const groups = {};
for (const word of words) {
  const key = word.split('').sort().join('');
  if (groups[key]) groups[key].push(word);
  else groups[key] = [word];
}
console.log('groups', Object.keys(groups).length); // groups 2
console.log(Object.values(groups)[0].join(' ')); // listen silent enlist

output:
groups 2
listen silent enlist

Walk the string from the last index down to zero and append each character. The loop order is the whole trick.

code:
function reverse(s) {
  let out = '';
  for (let i = s.length - 1; i >= 0; i--) {
    out += s[i];
  }
  return out;
}
const result = reverse('staging');
console.log(result, result.length); // gnigats 7

output:
gnigats 7

Turn the number into a string, walk it, and turn each character back into a number before adding.

code:
const digits = String(12345);
let sum = 0;
for (let i = 0; i < digits.length; i++) {
  sum += Number(digits[i]);
}
console.log(sum); // 15

output:
15

Adding to the counter inside the body does not skip the update at the end of the turn, so after printing 2 the counter jumps 2 to 4 and then moves on to 5. That is why 3 and 4 never print.

code:
for (let i = 0; i < 8; i++) {
  console.log(i);
  if (i === 2) i += 2;
}

output:
0
1
2
5
6
