Without braces a loop body is only the next single statement. The final console.log sits outside the loop, so it prints once instead of three times.

code:
const seen = [];
for (let i = 0; i < 3; i++)
  if (i % 2 === 0) seen.push('even ' + i);
console.log(seen.join(' | '));
console.log('printed once after the loop');

output:
even 0 | even 2
printed once after the loop

continue ends the current turn early but the loop still runs its update, so the counter keeps moving and the other four numbers are collected.

code:
const kept = [];
for (let i = 0; i < 5; i++) {
  if (i === 2) continue;
  kept.push(i);
}
console.log(kept.join(' ')); // 0 1 3 4

output:
0 1 3 4

One let loop variable is copied into a fresh binding on every turn, so each function remembers its own number. A var loop variable is shared, so all three functions see the final value.

code:
const withVar = [];
const withLet = [];
for (var v = 0; v < 3; v++) withVar.push(() => v);
for (let l = 0; l < 3; l++) withLet.push(() => l);
console.log(withVar.map((fn) => fn()).join(' ')); // 3 3 3
console.log(withLet.map((fn) => fn()).join(' ')); // 0 1 2

output:
3 3 3
0 1 2

A for loop with no condition at all would run forever, so break is the only thing stopping it. The break happens on the turn where the total reaches 10.

code:
let i = 0;
let total = 0;
for (;;) {
  i++;
  total += i;
  if (total >= 10) break;
}
console.log('i', i, 'total', total); // i 4 total 10

output:
i 4 total 10

Test the most specific rule first inside the loop. Building an array keeps the function easy to test and easy to read.

code:
function fizzbuzz(n) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) out.push('FizzBuzz');
    else if (i % 3 === 0) out.push('Fizz');
    else if (i % 5 === 0) out.push('Buzz');
    else out.push(String(i));
  }
  return out;
}
console.log(fizzbuzz(15).join(' '));

output:
1 2 Fizz 4 Buzz Fizz 7 8 Fizz Buzz 11 Fizz 13 14 FizzBuzz

for-of gives each object directly. A counter inside the loop gives you the total for free.

code:
const tests = [
  { id: 1, passed: true },
  { id: 2, passed: false },
  { id: 3, passed: true },
];
let passed = 0;
for (const test of tests) {
  if (test.passed) passed++;
  console.log(test.passed ? 'PASS' : 'FAIL', test.id);
}
console.log('passed', passed, 'of', tests.length); // passed 2 of 3

output:
PASS 1
FAIL 2
PASS 3
passed 2 of 3

The remainder from the modulo operator is the last digit. Dividing by 10 drops that digit and moves on to the next one.

code:
function sumDigitsOf(n) {
  let total = 0;
  while (n > 0) {
    total += n % 10;
    n = Math.floor(n / 10);
  }
  return total;
}
console.log(sumDigitsOf(9875)); // 29

output:
29

Splitting gives an array of words. An empty string splits into one empty word, so filter that case with an if.

code:
function countWords(text) {
  const words = text.split(' ');
  let count = 0;
  for (const word of words) {
    if (word !== '') count++;
  }
  return count;
}
console.log(countWords('ship it')); // 2
console.log(countWords('')); // 0

output:
2
0

